# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. ÜNİTE: YA İSTİKLAL YA ÖLÜM! — KURTULUŞ SAVAŞI\'NDA ÜÇ CEPHE</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Doğu Cephesi</text>\n  <text x="125" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Düşman: Ermeniler</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">• Birlik: Osmanlıdan kalan</text>\n  <text x="125" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">15. Kolordu (Düzenli Ordu)</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">• Komutan: Kâzım Karabekir</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kapanış: Gümrü Antlaşması</text>\n  <text x="125" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">(3 Aralık 1920 — İlk Siyasi Zafer)</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" fill="#334155">İlk açılan ve ilk kapanan cephedir.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">2. Güney Cephesi</text>\n  <text x="350" y="94" text-anchor="middle" font-size="11" fill="#881337">• Düşman: Fransızlar ve</text>\n  <text x="350" y="112" text-anchor="middle" font-size="11" fill="#881337">onların silahlandırdığı Ermeniler</text>\n  <text x="350" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">• Birlik: Kuva-yı Milliye (Halk)</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#881337">• Merkezler: Maraş, Urfa, Antep</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#881337">• Kapanış: Ankara Antlaşması</text>\n  <text x="350" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">(20 Ekim 1921 — Fransa ile)</text>\n  <text x="350" y="220" text-anchor="middle" font-size="10" fill="#881337">Düzenli ordu savaşmamıştır!</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Batı Cephesi</text>\n  <text x="575" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Düşman: Yunanlılar (İngiliz</text>\n  <text x="575" y="112" text-anchor="middle" font-size="11" fill="#14532d">destekli işgal kuvvetleri)</text>\n  <text x="575" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Birlik: Önce Kuva-yı Milliye,</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">sonra BMM Düzenli Ordusu</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" fill="#14532d">• Savaşlar: I. ve II. İnönü,</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11" fill="#14532d">Kütahya-Eskişehir, Sakarya, Büyük T.</text>\n  <text x="575" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Kapanış: Mudanya Ateşkesi (1922)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞU CEPHESİ VE GÜMRÜ ANTLAŞMASI\'NIN (3 ARALIK 1920) ÖNEMİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Doğu Harekâtı ve Kâzım Karabekir</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#713f12">• Mondros\'un 24. maddesine dayanarak Doğu</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#713f12">Anadolu\'da Ermeni devleti kurulmak istendi.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#713f12">• Kâzım Karabekir Paşa 15. Kolordu\'yu</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#713f12">dağıtmayarak BMM emrine girdi.</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" fill="#713f12">• Sarıkamış, Kars ve Gümrü kurtarıldı;</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#713f12">Ermenistan barış istemek zorunda kaldı.</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Yetim çocukları korudu: \'Yetimler Babası\'</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Gümrü Antlaşması\'nın Siyasi Önemi</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">1. BMM\'nin uluslararası alandaki İLK SİYASİ</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">ve ASKERÎ başarısıdır.</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#164e63">2. BMM\'yi ve Misakımillî\'yi tanıyan İLK</text>\n  <text x="520" y="154" text-anchor="middle" font-size="11" fill="#164e63">devlet Ermenistan olmuştur.</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#164e63">3. Ermenistan, Sevr Antlaşması\'nın geçersiz</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#164e63">olduğunu resmen kabul etmiştir.</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">4. Uluslararası belgede ilk kez \'TÜRKİYE\' adı geçti.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜNEY CEPHESİ KAHRAMANLARI VE KUVA-YI MİLLİYE DİRENİŞİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">1. Maraş Savunması</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Kahraman: Sütçü İmam</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#881337">• Rıdvan Hoca: \'Kalesinde bayrağı</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#881337">dalgalanmayan ülkede cuma</text>\n  <text x="125" y="154" text-anchor="middle" font-size="11" fill="#881337">namazı kılınamaz!\'</text>\n  <text x="125" y="178" text-anchor="middle" font-size="11" fill="#881337">• Kurtuluş: 12 Şubat 1920</text>\n  <text x="125" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Unvan: KAHRAMAN (1973)</text>\n  <text x="125" y="222" text-anchor="middle" font-size="10" fill="#881337">+ İstiklal Madalyası (1925)</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Urfa Savunması</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Kahraman: Ali Saip (Ursavaş)</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#581c87">• On İkiler (12\'ler) Direniş</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#581c87">Örgütü halkı teşkilatlandırdı.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#581c87">• Fransız işgal kuvvetleri</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#581c87">11 Nisan 1920\'de şehirden çekildi.</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Unvan: ŞANLI (1984)</text>\n  <text x="350" y="222" text-anchor="middle" font-size="10" fill="#581c87">+ İstiklal Madalyası (2016)</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Antep ve Adana</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Kahraman: Şahin Bey &amp; Karayılan</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#14532d">• Şahin Bey: \'Düşman cesedimi</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" fill="#14532d">çiğnemeden Antep\'e giremez!\'</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#14532d">• Adana/Toroslar: Tufan Bey, Tayyar</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" fill="#14532d">Rahmiye, Kılavuz Hatice</text>\n  <text x="575" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Unvan: GAZİ (8 Şubat 1921)</text>\n  <text x="575" y="222" text-anchor="middle" font-size="10" fill="#14532d">Sakarya Zaferi sonrası kurtuldu.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
